export default {id:'collections',label:'Les plantes',render:()=>`<section id="collections" class="collections section-pad"><div class="collection-top"><div><p class="eyebrow">05 / PETITES ET GRANDES RENCONTRES</p><h2>À chacun<br><em>sa nature.</em></h2></div><div><p>Un feuillage qui vous ressemble.<br>Une présence qui change tout.</p><div class="filters" role="group" aria-label="Filtrer les plantes"><button class="active" data-filter="all" aria-pressed="true">Toutes</button><button data-filter="interieur" aria-pressed="false">Intérieur</button><button data-filter="exterieur" aria-pressed="false">Extérieur</button></div></div></div><div class="plant-grid">${plants.map((p,i)=>`<button class="plant-card" data-plant="${i}" data-category="${p.category}"><div class="plant-image"><img loading="lazy" src="https://images.unsplash.com/${p.image}?auto=format&fit=crop&w=900&q=85" alt="${p.name}, photographie d’inspiration"><span>${p.tag}</span><b>↗</b></div><div class="plant-info"><h3>${p.name}</h3><span>${p.latin}</span></div></button>`).join('')}</div><p class="catalog-note">Sélection illustrative · espèces et disponibilités à confirmer avec GreenNouala.</p></section>`};
